const slug = ($json.project_slug ?? $json['Project Slug'] ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('Project Slug is required.');
const regenRaw = ($json.regen_ids ?? $json['Shot IDs to Regenerate (optional)'] ?? '').toString();
const regenIds = regenRaw.split(/[,\s]+/).map((x) => x.trim().toLowerCase()).filter(Boolean);
return [{ json: { slug, payloadB64: Buffer.from(JSON.stringify({ slug, regen_ids: regenIds })).toString('base64') } }];

const res = JSON.parse(($json.stdout ?? '').toString().trim());
if (!res.ok) throw new Error(res.error || 'Failed to load shot plan.');
if (!res.shots.length) throw new Error('All shot images already exist. Enter shot ids (e.g. shot_002) in the form to force regeneration.');
return [{ json: { slug: res.slug, shots: res.shots } }];

const shot = $json;
const lines = ['Cinematic 16:9 film still, single frame.'];
if (shot.style_notes) lines.push('Overall style: ' + shot.style_notes);
for (const c of (shot.character_blocks ?? [])) {
  lines.push(c.name + ': ' + c.visual_description + ' Use the attached reference image(s) of ' + c.name + ' and keep facial features, hairstyle, body type, and clothing exactly consistent.');
}
lines.push('Scene: ' + shot.image_prompt);
lines.push('Photorealistic, cinematic lighting. No text, captions, watermarks, or borders.');
return [{ json: {
  shotId: shot.id,
  slug: shot.slug,
  promptB64: Buffer.from(JSON.stringify({ shotId: shot.id, slug: shot.slug, prompt: lines.join('\n') })).toString('base64'),
}}];

const srcs = $('Build Gemini Request').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json ?? {};
  let shotId = '';
  try { shotId = JSON.parse(srcs[i].json.stdout).shotId; } catch (e) {}
  const cands = Array.isArray(resp.candidates) ? resp.candidates : [];
  let img = null;
  for (const c of cands) {
    const parts = (c.content && Array.isArray(c.content.parts)) ? c.content.parts : [];
    for (const part of parts) {
      if (part.inlineData && part.inlineData.data) { img = part.inlineData.data; break; }
    }
    if (img) break;
  }
  if (!img) {
    const reason = (resp.promptFeedback && resp.promptFeedback.blockReason)
      || (cands[0] && cands[0].finishReason)
      || 'no image part in Gemini response';
    throw new Error('Shot ' + (shotId || ('#' + i)) + ' failed: ' + reason);
  }
  const slug = $('Build Shot Prompt').all()[i].json.slug;
  const destDir = '/home/node/files/films/' + slug + '/shots';
  const destPath = destDir + '/' + shotId + '.png';
  const SIZE = 60000;
  const nChunks = Math.max(1, Math.ceil(img.length / SIZE));
  for (let s = 0; s < nChunks; s++) {
    out.push({ json: {
      fileId: slug + '_' + shotId, destDir, destPath, seq: s,
      isLast: (s === nChunks - 1) ? 1 : 0,
      chunkB64: img.slice(s * SIZE, (s + 1) * SIZE),
    }});
  }
}
return out;
